#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Wrapper for requests module with Velocity specific settings.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import json
import re

import requests
from copy import deepcopy
from re import sub
from velocity_communicator.log.log import Log

requests.packages.urllib3.disable_warnings(
    requests.packages.urllib3.exceptions.InsecureRequestWarning
)


class RestQueryException(Exception):
    """
        Exception used with RestQuery errors (eg. response's return status code
        mismatches with expected one). Inherited from exception class.
    """

    pass


class BadJsonException(Exception):
    """
        Exception used when testing JSON data. Inherited from exception class.
    """

    pass


class RestQuery(object):
    """
        Wrapper for requests.get/post/put/delete request along with parameters
        parsing methods.

        Arguments:
            method (str): Get/put/post/delete request type.
            path (str): Url to Velocity's service.
                proxies (str, optional): Address of proxy server.

        Keyword Arguments:
            auth_token (str): Possible authorization token, that is being
                appended as X-Auth-Token HTTP header to the request.
            data (str): Payload of the message.
            headers (dict, optional): Extra HTTP headers that are needed to
                fulfill the request.
            result (list): Expected HTTP result code of the response. If
                some other result code is returned by request call, the
                RestQueryException is raised.
            accept_type (str): specifies certain media types which are
                acceptable for the response.
            content_type (str): the content type of payload
            validate_json (bool): checks if passed JSON data is valid.
            stream (str, optional) if a contents of a file is used as a
                request payload instead of the data given as parameter
                to the constructor.

        Raises:
            BadJsonException: when passed data have wrong JSON format and
                validate_json was set to True in kwargs.
    """

    logger = Log.get_logger('query')
    requests_mapping = {
        'post': requests.post,
        'get': requests.get,
        'put': requests.put,
        'delete': requests.delete
    }

    def __init__(self, path, method, **kwargs):
        """
            Creates a REST query request.

            Arguments:
                path (str): Path to the rest object (without the host part).
                method (str): HTTP method used in the request, possible values
                    are 'post', 'get', 'put' and 'delete'
                kwargs (dict): dict with optional parameters: data, result,
                    proxies, auth_token, accept_type, content_type, headers,
                    validate_json, stream
        """

        self._path = path
        self._method = self.requests_mapping[method]
        self._result = kwargs.get('result', [200])
        self._proxies = kwargs.get('proxies', None)
        self._auth_token = kwargs.get('auth_token', None)
        self._headers = kwargs.get('headers', {})
        self._headers['Content-Type'] = kwargs.get(
            'content_type', 'application/json'
        )
        self._headers['Accept'] = kwargs.get('accept_type', 'application/json')
        if self._auth_token:
            self._headers['X-Auth-Token'] = self._auth_token

        if 'stream' in kwargs.keys():
            self._data = kwargs['stream']
        else:
            self._data = kwargs.get('data', None)

        if kwargs.get('validate_json', None):
            try:
                json.loads(self._data)
            except json.decoder.JSONDecodeError as ex:
                raise BadJsonException(
                    'Bad data format:{}'.format(ex)
                )
        if self._proxies:
            self.logger.debug(f"Proxies: {self._proxies}")

    def request(self):
        """
            Makes a REST query request.

            Use case::

                response = RestQuery(
                    url, "get", data=json.dumps(data), result=[200, 201],
                    content_type='application/json', auth_token=token,
                    accept_type='application/json'
                ).request()

            Raises:
                RestQueryException: when response's status code mismatches.

            Return:
                The default implementation is to return the python data
                structure containing the response body. Exception is raised,
                if the request fails, e.g. the server doesn't respond or the
                HTTP result code is something else than the expected one.
        """
        self.logger.info(f"Sending {self._method.__name__} request to Velocity - {self._path}")

        headers_for_log = deepcopy(self._headers)
        hide_headers = ['Authorization', 'X-Auth-Token']
        for header_name in hide_headers:
            if header_name in headers_for_log:
                headers_for_log[header_name] = '*hidden*'

        self.logger.debug(
            f"Request:\n\tURL: {self._path}\n\tHeaders: {headers_for_log}\n\tPayload: "
            f"{None if not self._data else self._remove_xml_password(self._data)}"
        )

        response = self._method(
            self._path, data=self._data, headers=self._headers,
            proxies=self._proxies, verify=False
        )
        if response.status_code in [403]:
            if "LICENSE_REQUIRED" in response.text:
                raise RestQueryException(f'Request to Velocity failed with status code: {response.status_code}.\n'
                                         f'Error message: {response.text}')
        return self._analyze_result(response)

    def _analyze_result(self, response):
        text = sub(r'(?<="token"\:").+?(?=")', '*hidden*', response.text)
        self.logger.debug(f"Response:\n\tStatus: {response.status_code}\n\t"
                          f"Headers: {response.headers}\n\tText: {text}")
        if response.status_code in self._result:
            return self._parse_result_parameters(response)
        raise RestQueryException(
            f"Status code mismatch, expected {str(self._result)}, "
            f"got {response.status_code}  - URL: {response.url}\n{response.text}",
        )

    @staticmethod
    def _remove_xml_password(string):
        if isinstance(string, bytes):
                try:
                    string = string.decode('utf-8')
                except UnicodeDecodeError:
                    # Not decodable, just return placeholder
                    return "<binary data>"
        return re.sub(
            r'<password>(.*)</password>', '<password>********</password>',
            string
        )

    @staticmethod
    def _parse_result_parameters(response):
        content_type = response.headers.get('Content-Type', None)
        #if content_type == 'application/json':
        if content_type == None:
            return None
        elif 'application/json' in content_type.split(";")[0]:
            return json.loads(response.text)
        elif content_type.split(";")[0] in [
                'application/tbml',
                'application/xml',
                'text/csv',
                'text/plain',
                'application/vnd.spirent-velocity.topology.tosca+yaml'
            ]:
            return response.text
        elif content_type.split(";")[0] == "application/zip":
            return response.content
        return None
